while True:
    d = robot.distance()
    if d < 30:
        robot.left(30)
    else:
        robot.forward(50)

while True:
    left_on, right_on = robot.line()
    if left_on and right_on:
        robot.forward(40)
    elif left_on:
        robot.left(8)
    elif right_on:
        robot.right(8)
    else:
        robot.forward(20)

while True:
    d = robot.distance()
    if d < 25:
        robot.right(25)
    else:
        robot.forward(40)
